-- MP-0053: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='gabungan-rakyat-sabah' and type='alliance') then raise exception 'MP-0053: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='perikatan-nasional' and type='alliance') then raise exception 'MP-0053: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0053: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('ronald-kiandee','suhaimi-nasir','khairul-firdaus-akbar-khan') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0053: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('beluran','libaran','batu sapi') and slug not in ('ronald-kiandee','suhaimi-nasir','khairul-firdaus-akbar-khan')) then raise exception 'MP-0053: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0053:%' and (m.source_type <> 'editorial' or e.slug not in ('ronald-kiandee','suhaimi-nasir','khairul-firdaus-akbar-khan') or m.import_key not like 'MP-0053:' || e.slug || ':%')) then raise exception 'MP-0053: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ronald-kiandee','Ronald Kiandee','opposition','Member of the Dewan Rakyat','Beluran','Sabah','Ronald Kiandee represents Beluran, Sabah, in the Dewan Rakyat. Parliament records affiliation with Perikatan Nasional (PN).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4222','/portraits/ronald-kiandee.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P183.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4222"}, {"label": "Bersatu suspension · personal statement, 10 March 2026", "url": "https://www.thestar.com.my/news/nation/2026/03/10/bersatu-vp-ronald-kiandee-suspended-for-two-terms-refuses-to-appeal"}]'::jsonb from public.entities parent where parent.slug='perikatan-nasional' and parent.type='alliance' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'suhaimi-nasir','Suhaimi Nasir','government','Member of the Dewan Rakyat','Libaran','Sabah','Suhaimi Nasir represents Libaran, Sabah, in the Dewan Rakyat. Affiliated with UMNO.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4223','/portraits/suhaimi-nasir.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P184.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4223"}, {"label": "UMNO · current Libaran division chief, 9 April 2026", "url": "https://umno-online.my/2026/04/09/perkukuh-akar-umbi-fokus-penyatuan-demi-masa-hadapan-umno-suhaimi-nasir/"}]'::jsonb from public.entities parent where parent.slug='umno' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'khairul-firdaus-akbar-khan','Khairul Firdaus Akbar Khan','government','Deputy Minister of Human Resources','Batu Sapi','Sabah','Khairul Firdaus Akbar Khan represents Batu Sapi, Sabah, in the Dewan Rakyat. Current role: Deputy Minister of Human Resources. Parliament records affiliation with Gabungan Rakyat Sabah (GRS).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4224','/portraits/khairul-firdaus-akbar-khan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P185.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4224"}, {"label": "GRS MPs · current representation, 9 January 2026", "url": "https://gagasanrakyat.my/empat-kerusi-parlimen-sabah-kekal-mahkamah-persekutuan-tolak-permohonan-bersatu/"}]'::jsonb from public.entities parent where parent.slug='gabungan-rakyat-sabah' and parent.type='alliance' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('ronald-kiandee','suhaimi-nasir','khairul-firdaus-akbar-khan') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0053: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0053:khairul-firdaus-akbar-khan:national-training-week-launch','Launch National Training Week 2026 in Sandakan','Education','achieved',null,null,null,null,'2026-07-19','https://www.malaymail.com/amp/news/malaysia/2026/07/19/from-ai-prompting-to-vehicle-maintenance-thousands-of-free-courses-offered-to-malaysians-during-national-training-week/228207','The HRD Corp statement reports Khairul Firdaus officiating the 18 July launch, ahead of free learning activities beginning on 20 July.','Published 19 July about the previous evening’s launch. Achieved covers the launch only, not course completion, participant employment or delivery of every roadshow stop. HRD Corp and KESUMA organised the programme.','2026-11-10','editorial',false from public.entities e where e.slug='khairul-firdaus-akbar-khan' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

commit;
